@startuml

class Song {
  + title : string
  + year : int
  + length : time
  + genre : string
}

class Artist {
  + name : string
  + birthDate : date
  + website : string
}

class User {
  + userID : int
  + name : string
  + address : string
}

abstract class UserType {}

class RegularUser {
  + VATNumber : string
}

class BusinessUser {}

class Album {
  + trackNumber : int
}

class Single {}

class Hit {}

RegularUser --|> UserType
BusinessUser --|> UserType
Song "1" -- "1" Artist
User "*" -- "0..*" Song
User "*" -- "0..*" Album
Album "*" -- "1..*" Hit
Hit "1" -- "1" Single

@enduml

